#pragma once
static const char DASHBOARD[] = R"HTML(<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>LRF → TF03</title><style>body{background:#101820;color:#edf5fa;font:16px system-ui;margin:32px auto;padding:0 20px;max-width:900px}section{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:16px}.card{background:#1a2732;padding:24px;border-radius:14px}strong{font-size:36px}p{line-height:1.6}a{color:#94d5ff}#error,#simulation{color:#ffc979}</style><h1>LRF → Benewake TF03</h1><p id="error" role="status"></p><p id="simulation"></p><section><div class="card"><h2>Дальномер</h2><strong id="distance">—</strong><p id="rx-rate">Приём: — Гц</p><p id="sensor">Ожидание</p></div><div class="card"><h2>Выход в полётник</h2><p>TF03 · 115200 бод · GPIO10</p><p id="tx-rate">Отправка: — Гц</p><p id="tx">—</p><p>Приём полётником неизвестен: TF03 не возвращает подтверждение.</p></div><div class="card"><h2>Wi-Fi</h2><p id="wifi">—</p><p id="uptime">—</p></div></section><p><a href="/api/status">Статус JSON</a> · <a href="/api/lidar">Лидар JSON</a> · <a href="/api/fc">Выход JSON</a></p><script>
let busy=false;const el=id=>document.getElementById(id);
async function update(){if(busy)return;busy=true;try{const r=await fetch('/api/status',{cache:'no-store',signal:AbortSignal.timeout(2500)});if(!r.ok)throw Error(r.status);const s=await r.json();el('error').textContent='';el('rx-rate').textContent='Приём лидара: '+s.lidar.rate_hz.toFixed(1)+' Гц';el('tx-rate').textContent='Отправка TF03: '+s.fc.tx_rate_hz.toFixed(1)+' Гц';el('simulation').textContent=s.lidar.simulated?'СИМУЛЯЦИЯ: тестовое расстояние. Не использовать для полёта.':'';el('distance').textContent=s.lidar.distance_m.toFixed(2)+' м';el('sensor').textContent=(s.lidar.valid?'Свежие данные':s.lidar.connected?'Невалидное измерение — передаётся 0':'Нет данных лидара — передаётся 0')+' · кадров '+s.lidar.good+' · ошибок '+s.lidar.bad;el('tx').textContent='Записано в UART: '+s.fc.tx_frames+' · отброшено: '+s.fc.tx_dropped;el('wifi').textContent=s.wifi.ssid+' · '+s.wifi.ap_ip+' · клиентов '+s.wifi.clients;el('uptime').textContent='Работает '+Math.floor(s.uptime_ms/1000)+' с';}catch(e){el('error').textContent='Нет связи с ESP. Показания устарели.';el('distance').textContent='—';el('rx-rate').textContent='Приём: — Гц';el('tx-rate').textContent='Отправка: — Гц';}finally{busy=false;}}update();setInterval(update,1000);
</script></html>)HTML";
